# Helper function to tag questions per board
def tag_bank(bank, board_name, class_str="Matric"):
    res = []
    for q in bank:
        item = dict(q)
        item["pyqTag"] = f"{board_name} {class_str} Exam Subjective Question ({item['marks']} Marks)"
        res.append(item)
    return res

